//! The rules a motorway is generated by, once its roads are on the map: which of
//! its stretches go on a bridge, through a tunnel or along the ground; where a road
//! crossing another needs a bridge to do it; and how the land is cut and filled to
//! meet what stays on the ground.
//!
//! Every rule reads the **natural** land: the country's height from the roads
//! that are not the corridor's, the parts' rims and toes, and the hills, before
//! anything is cut or filled for the motorway. A motorway is fitted to the land,
//! not the other way round, so its own heights are left out of it.
//!
//! Whether a road goes on a bridge or through a tunnel reads the land the roads
//! round it leave besides: beside another road on an embankment the land is the
//! embankment's slope, and beside one in a cutting the cutting's, however the
//! natural land lies. A slip road beside a motorway is over the motorway's
//! embankment, not the country under it.
//!
//! An ordinary road asked to have its structures chosen
//! ([`Places::structured_roads`](super::Places::structured_roads)) is read by the
//! same rules: it is no motorway and belongs to no corridor, but it is fitted to
//! the land the same way.

use roadgen_core::geometry::plan::{ring_contains, PlanPoint, Segments};
use roadgen_core::geometry::{Grid, Point3};
use roadgen_core::id::RoadId;
use roadgen_core::map::Map;
use roadgen_core::structure::{
    self, BridgeForm, BridgeSpec, RoadSpan, StructureSpec, TunnelForm, TunnelSpec,
};
use roadgen_core::FormOfWay;

use super::corridor::StructureMode;
use super::land::{at_grade_edges, plan_of, Line, Rise};
use crate::ground::Field;

/// Above the land by more than this, a road whose structures are chosen goes on a
/// bridge, metres;
/// and the bridge reaches out to where it is this far above.
const BRIDGE: f64 = 8.0;
const ABUTMENT: f64 = 5.0;
/// Below the land by more than a tunnel's height and this much cover, it goes in a
/// tunnel; and the tunnel reaches out to where the cover is this thin, metres.
const COVER: f64 = 10.0;
const PORTAL: f64 = 2.0;
/// The shortest structure the rules make, and the shortest stretch of ground they
/// leave between two, metres.
const SHORTEST: f64 = 30.0;
const GAP: f64 = 50.0;
/// How far apart a road is read, metres.
const STEP: f64 = 5.0;
use roadgen_core::structure::{CLEARANCE, OVERPASS_DECK};
/// A fill's and a cut's slope: metres out for every metre down or up.
const FILL: f64 = 1.8;
const CUT: f64 = 1.2;
/// The furthest out a slope is run before it is given up on, metres.
const FURTHEST: f64 = 80.0;

/// The natural land, before the motorway.
pub(crate) struct Natural<'a> {
    pub field: Option<Field>,
    pub rises: &'a [Rise],
}

impl Natural<'_> {
    pub fn height(&self, x: f64, y: f64) -> f64 {
        self.field.as_ref().map_or(0.0, |field| field.height(x, y))
            + self.rises.iter().map(|rise| rise.at([x, y])).sum::<f64>()
    }
}

/// The land round a road as the roads beside it leave it: the natural land, and
/// the embankments and cuttings the others stand on — a slope out from each
/// edge, square to it, [`FILL`] down or [`CUT`] up, as [`earthworks`] makes it.
/// A slip road beside a motorway on an embankment has that embankment's slope
/// under it, not the natural land, however high it stands over the natural land.
struct Beside {
    points: Grid<Ground>,
}

/// A point of a road on the ground that stands off the natural land, as
/// [`Beside`] reads it.
#[derive(Debug, Clone, Copy)]
struct Ground {
    road: usize,
    at: Point3,
    /// The way the road runs there, in plan: its slopes run out square to it.
    along: [f64; 2],
    /// How far out from `at` its edge is: none for a point on the edge.
    half: f64,
    /// How far it stands off the natural land: over it on an embankment, under
    /// it in a cutting.
    difference: f64,
}

/// The way a line runs at each of its points, in plan, from the points either
/// side.
fn directions(points: &[Point3]) -> Vec<[f64; 2]> {
    (0..points.len())
        .map(|index| {
            let a = points[index.saturating_sub(1)];
            let b = points[(index + 1).min(points.len() - 1)];
            let (dx, dy) = (b.x - a.x, b.y - a.y);
            let length = dx.hypot(dy).max(1e-9);
            [dx / length, dy / length]
        })
        .collect()
}

impl Beside {
    fn of(points: impl Iterator<Item = Ground>) -> Beside {
        let mut grid = Grid::new(FURTHEST);
        // As little off the land as `slopes` leaves be.
        for point in points.filter(|point| point.difference.abs() >= 0.3) {
            grid.insert([point.at.x, point.at.y], [point.at.x, point.at.y], point);
        }
        Beside { points: grid }
    }

    /// The land at `p` from the roads beside road `road`: the highest it can
    /// stand and the lowest, the natural land's `natural` between them. A slope
    /// is read where `p` is square out from a point of the other road — within
    /// half the most a road's points are apart — not off its end, as the ground
    /// beside two roads side by side rising on to their bridges is not.
    fn land(&self, road: usize, p: Point3, natural: f64) -> (f64, f64) {
        let (mut high, mut low) = (natural, natural);
        for point in self.points.around(p.x, p.y) {
            if point.road == road {
                continue;
            }
            let (dx, dy) = (p.x - point.at.x, p.y - point.at.y);
            let [tx, ty] = point.along;
            if (dx * tx + dy * ty).abs() > STEP / 2.0 + 0.5 {
                continue;
            }
            let out = ((tx * dy - ty * dx).abs() - point.half).max(0.0);
            if out > FURTHEST {
                continue;
            }
            if point.difference > 0.0 {
                high = high.max(point.at.z - out / FILL);
            } else {
                low = low.min(point.at.z + out / CUT);
            }
        }
        (high, low)
    }
}

/// A road whose structures are chosen, read along its line: at each station its
/// point, the natural land's height there, how far out its edges reach, whether
/// it is over water, and whether it is on a structure already.
struct Reading {
    id: RoadId,
    corridor: Option<String>,
    shared: bool,
    carriageway: bool,
    stations: Vec<f64>,
    points: Vec<Point3>,
    along: Vec<[f64; 2]>,
    natural: Vec<f64>,
    half: Vec<f64>,
    wet: Vec<bool>,
    fixed: Vec<bool>,
}

impl Reading {
    /// The road at each of its own vertices; where two are further apart than a
    /// step — a straight line drawn end to end — every step between them too.
    fn of(
        map: &Map,
        id: &RoadId,
        corridor: &Option<String>,
        shared: bool,
        natural: &Natural,
        water: &[Vec<PlanPoint>],
    ) -> Option<Reading> {
        let road = map.road(id)?;
        if road.is_connector() {
            return None;
        }
        let vertices = road.reference_line.samples(map.metadata.sampling).ok()?;
        let between: Vec<f64> = vertices
            .windows(2)
            .flat_map(|pair| {
                let (a, b) = (pair[0].station, pair[1].station);
                let count = if b - a > STEP + 0.5 {
                    ((b - a) / STEP).ceil() as usize
                } else {
                    1
                };
                (1..count).map(move |k| a + (b - a) * k as f64 / count as f64)
            })
            .collect();
        let samples = if between.is_empty() {
            vertices
        } else {
            road.reference_line
                .samples_including(map.metadata.sampling, &between)
                .ok()?
        };
        let mut reading = Reading {
            id: id.clone(),
            corridor: corridor.clone(),
            shared,
            carriageway: matches!(
                road.form,
                FormOfWay::Motorway | FormOfWay::MultipleCarriageway
            ),
            stations: Vec::with_capacity(samples.len()),
            points: Vec::with_capacity(samples.len()),
            along: Vec::new(),
            natural: Vec::with_capacity(samples.len()),
            half: Vec::with_capacity(samples.len()),
            wet: Vec::with_capacity(samples.len()),
            fixed: Vec::with_capacity(samples.len()),
        };
        for sample in samples {
            let (station, p) = (sample.station, sample.point);
            reading.stations.push(station);
            reading.points.push(p);
            reading.natural.push(natural.height(p.x, p.y));
            reading
                .half
                .push(structure::road_extent(map, id, station).map_or(0.0, |(l, r)| l.max(-r)));
            reading
                .wet
                .push(water.iter().any(|ring| ring_contains(ring, [p.x, p.y])));
            reading.fixed.push(road.structure.at(station).is_some());
        }
        reading.along = directions(&reading.points);
        Some(reading)
    }

    /// Each station classified, with how far off the land it stands: over the
    /// highest the roads `beside` it leave the land, or under the lowest. `road`
    /// is its index among the roads `beside` reads.
    fn rows(&self, road: usize, beside: &Beside, deep: f64) -> Vec<(f64, f64, Class)> {
        (0..self.stations.len())
            .map(|index| {
                let p = self.points[index];
                let (high, low) = beside.land(road, p, self.natural[index]);
                let d = if p.z > high {
                    p.z - high
                } else {
                    (p.z - low).min(0.0)
                };
                let class = if self.fixed[index] {
                    Class::Fixed
                } else if self.wet[index] || d > BRIDGE {
                    Class::Bridge
                } else if d < -(deep + COVER) {
                    Class::Tunnel
                } else {
                    Class::Ground
                };
                (self.stations[index], d, class)
            })
            .collect()
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum Class {
    Ground,
    Bridge,
    Tunnel,
    /// Already on a structure the caller put there.
    Fixed,
}

/// A corridor's rules, as [`choose_structures`] reads them: its name, how its
/// structures are chosen, and whether its carriageways share a deck.
pub(crate) type Modes = [(String, StructureMode, bool)];

/// A stretch of a carriageway the rules put on a bridge, kept back to be put on a
/// deck shared with the other carriageway's.
struct Run {
    road: RoadId,
    corridor: String,
    from: f64,
    to: f64,
    /// The road at each of its vertices: station, point, height off the land,
    /// class.
    rows: Vec<(f64, Point3, f64, Class)>,
    /// Whether any of it is over water.
    wet: bool,
}

impl Run {
    /// The sample nearest `point` in plan: its index and how far off it is.
    fn nearest(&self, point: Point3) -> (usize, f64) {
        self.rows
            .iter()
            .enumerate()
            .map(|(index, row)| (index, row.1.horizontal_distance_to(point)))
            .min_by(|a, b| a.1.total_cmp(&b.1))
            .unwrap_or((0, f64::INFINITY))
    }

    /// The point at `station`, the nearest sample's.
    fn point_at(&self, station: f64) -> Point3 {
        self.rows
            .iter()
            .min_by(|a, b| (a.0 - station).abs().total_cmp(&(b.0 - station).abs()))
            .map_or(Point3::new(0.0, 0.0, 0.0), |row| row.1)
    }

    /// The direction of the road in plan at sample `index`, from its neighbours.
    fn direction(&self, index: usize) -> [f64; 2] {
        let a = self.rows[index.saturating_sub(1)].1;
        let b = self.rows[(index + 1).min(self.rows.len() - 1)].1;
        let (dx, dy) = (b.x - a.x, b.y - a.y);
        let length = dx.hypot(dy).max(1e-9);
        [dx / length, dy / length]
    }

    /// Whether `other`, on another road, runs beside this run for some of its
    /// length: a point inside its run lies square to the side of a point inside
    /// this one — projected onto this run, it falls within it, not off past
    /// either end — no further off than [`BESIDE`] and not on the line itself,
    /// with the two running the same way or opposite ways. Two pieces of one
    /// carriageway end to end are never beside each other: one runs on from the
    /// other along its line, not to its side.
    fn beside(&self, other: &Run) -> bool {
        if self.road == other.road {
            return false;
        }
        let inside = |run: &Run, index: usize| {
            let station = run.rows[index].0;
            station > run.from + 1e-6 && station < run.to - 1e-6
        };
        (0..other.rows.len())
            .filter(|index| inside(other, *index))
            .any(|index| {
                let p = other.rows[index].1;
                let (near, _) = self.nearest(p);
                if !inside(self, near) {
                    return false;
                }
                let here = self.rows[near].1;
                let [tx, ty] = self.direction(near);
                let (dx, dy) = (p.x - here.x, p.y - here.y);
                let along = dx * tx + dy * ty;
                let lateral = (tx * dy - ty * dx).abs();
                // Half the way to the next sample either side: square to this one.
                let half = [near.saturating_sub(1), (near + 1).min(self.rows.len() - 1)]
                    .iter()
                    .map(|n| self.rows[*n].1.horizontal_distance_to(here))
                    .fold(0.0, f64::max)
                    / 2.0
                    + 0.5;
                let [ox, oy] = other.direction(index);
                along.abs() <= half
                    && lateral > 0.5
                    && lateral <= BESIDE
                    && (ox * tx + oy * ty).abs() >= PARALLEL
            })
    }
}

/// How nearly two carriageways have to run the same way, or opposite ways, to
/// share a deck: the cosine of the angle between them.
const PARALLEL: f64 = 0.94;

/// How far apart two carriageways' reference lines may be and still share a deck,
/// metres: a median and a carriageway's width, about.
const BESIDE: f64 = 2.0 * structure::MEDIAN;

/// Chooses the structures of every road in `roads` whose corridor leaves them to
/// the land, and of every road there of no corridor — an ordinary road asked to
/// have its structures chosen the same way. Returns the notes worth telling the
/// caller.
pub(crate) fn choose_structures(
    map: &mut Map,
    roads: &[(RoadId, Option<String>)],
    modes: &Modes,
    natural: &Natural,
    water: &[Vec<PlanPoint>],
) -> Vec<String> {
    let mut notes = Vec::new();
    let tunnel = TunnelSpec::default();
    let deep = tunnel.clear_height + tunnel.lining;
    let mode_of = |corridor: &Option<String>| {
        corridor
            .as_ref()
            .and_then(|corridor| modes.iter().find(|(name, _, _)| name == corridor))
    };
    let readings: Vec<Reading> = roads
        .iter()
        .filter_map(|(id, corridor)| {
            let mode = mode_of(corridor);
            if !mode.is_none_or(|(_, mode, _)| *mode == StructureMode::Auto) {
                return None;
            }
            let shared = mode.is_some_and(|(_, _, shared)| *shared);
            Reading::of(map, id, corridor, shared, natural, water)
        })
        .collect();
    // Every other road stays where it is: on the ground but where it is on a
    // structure already.
    let mut others: Vec<Ground> = Vec::new();
    let rest = map.roads.iter().filter(|road| {
        !road.is_connector() && !readings.iter().any(|reading| reading.id == road.id)
    });
    for (index, road) in (readings.len()..).zip(rest) {
        for (left, right) in at_grade_edges(map, road) {
            for edge in [every_step(&left), every_step(&right)] {
                for (p, along) in edge.iter().zip(directions(&edge)) {
                    others.push(Ground {
                        road: index,
                        at: *p,
                        along,
                        half: 0.0,
                        difference: p.z - natural.height(p.x, p.y),
                    });
                }
            }
        }
    }
    // Which of them stand on the ground, which the land beside each is read
    // from. A road read as off the ground leaves no slope for the others to
    // stand clear of, so it has to be off the ground in the end: every stretch
    // starts off it that stands far enough off the natural land — or over
    // water — and is put back on it while it does not stand far enough off the
    // land the others on the ground leave, or is too short a stretch to go on a
    // structure. Each stretch put back can only bring the land up round the
    // others, so this ends.
    let off_natural = |reading: &Reading, index: usize| {
        let d = reading.points[index].z - reading.natural[index];
        !reading.fixed[index] && (reading.wet[index] || d > BRIDGE || d < -(deep + COVER))
    };
    let mut off: Vec<Vec<bool>> = readings
        .iter()
        .map(|reading| {
            (0..reading.stations.len())
                .map(|index| off_natural(reading, index))
                .collect()
        })
        .collect();
    let mut rows: Vec<Vec<(f64, f64, Class)>>;
    loop {
        let on_ground = readings
            .iter()
            .zip(&off)
            .enumerate()
            .flat_map(|(road, (reading, off))| {
                (0..reading.stations.len())
                    .filter(move |index| !off[*index] && !reading.fixed[*index])
                    .map(move |index| Ground {
                        road,
                        at: reading.points[index],
                        along: reading.along[index],
                        half: reading.half[index],
                        difference: reading.points[index].z - reading.natural[index],
                    })
            });
        let beside = Beside::of(on_ground.chain(others.iter().copied()));
        rows = readings
            .iter()
            .enumerate()
            .map(|(road, reading)| reading.rows(road, &beside, deep))
            .collect();
        let next: Vec<Vec<bool>> = rows
            .iter()
            .zip(&off)
            .map(|(rows, off)| {
                let mut next = vec![false; rows.len()];
                for (kind, extend) in [(Class::Bridge, ABUTMENT), (Class::Tunnel, deep + PORTAL)] {
                    for (from, to) in runs_of(rows, kind, extend) {
                        for (index, row) in rows.iter().enumerate() {
                            if row.2 == kind && row.0 >= from && row.0 <= to {
                                next[index] = off[index];
                            }
                        }
                    }
                }
                next
            })
            .collect();
        if next == off {
            break;
        }
        off = next;
    }

    // The bridges of the carriageways that share a deck, kept back until every
    // road's are known.
    let mut kept: Vec<Run> = Vec::new();
    for (reading, rows) in readings.iter().zip(rows) {
        let Reading {
            id,
            corridor,
            shared,
            carriageway,
            points,
            ..
        } = reading;
        let (shared, carriageway) = (*shared, *carriageway);
        let wet: Vec<f64> = reading
            .stations
            .iter()
            .zip(&reading.wet)
            .filter(|(_, wet)| **wet)
            .map(|(station, _)| *station)
            .collect();
        let Some(road) = map.road(id) else { continue };
        let over_water = |from: f64, to: f64| wet.iter().any(|s| *s >= from && *s <= to);
        // A bridge reaching out to one already there — a flyover's, over what it
        // crosses — meets it end to end: a strip of road on the ground between
        // the two would stand as high as the decks, and the land with it.
        let placed: Vec<(f64, f64)> = road
            .structure
            .spans()
            .iter()
            .map(|span| (span.from, span.to))
            .collect();
        let meet = |(from, to): (f64, f64)| {
            let near = |a: f64, b: f64| a <= b + 1e-6 && b - a <= STEP + 1.0;
            let from = placed
                .iter()
                .find(|(_, end)| near(*end, from))
                .map_or(from, |(_, end)| *end);
            let to = placed
                .iter()
                .find(|(start, _)| near(to, *start))
                .map_or(to, |(start, _)| *start);
            (from, to)
        };
        for (kind, extend) in [(Class::Bridge, ABUTMENT), (Class::Tunnel, deep + PORTAL)] {
            let mut runs = runs_of(&rows, kind, extend);
            if kind == Class::Bridge {
                runs = runs.into_iter().map(meet).collect();
            }
            for (from, to) in runs {
                if kind == Class::Bridge && shared && carriageway {
                    kept.push(Run {
                        road: id.clone(),
                        corridor: corridor.clone().unwrap_or_default(),
                        from,
                        to,
                        rows: rows
                            .iter()
                            .zip(points)
                            .map(|(row, p)| (row.0, *p, row.1, row.2))
                            .collect(),
                        wet: over_water(from, to),
                    });
                    continue;
                }
                let spans = [RoadSpan::new(id.clone(), from, to)];
                let spec = match kind {
                    Class::Bridge => bridge_spec(to - from, over_water(from, to)),
                    _ => StructureSpec::Tunnel(TunnelSpec {
                        form: TunnelForm::Bored,
                        ..TunnelSpec::default()
                    }),
                };
                if let Err(error) = structure::place(map, &spans, &spec) {
                    notes.push(format!("{id} {from:.0}–{to:.0} m: no structure: {error}"));
                }
            }
        }
    }
    for deck in shared_decks(&kept) {
        let spans: Vec<RoadSpan> = deck
            .iter()
            .map(|(index, from, to)| RoadSpan::new(kept[*index].road.clone(), *from, *to))
            .collect();
        let longest = spans.iter().map(RoadSpan::length).fold(0.0, f64::max);
        let wet = deck.iter().any(|(index, _, _)| kept[*index].wet);
        if spans.len() > 1 && structure::place(map, &spans, &bridge_spec(longest, wet)).is_ok() {
            continue;
        }
        // On a deck of its own, as it would be without one to share.
        for (index, _, _) in &deck {
            let run = &kept[*index];
            let spans = [RoadSpan::new(run.road.clone(), run.from, run.to)];
            if let Err(error) =
                structure::place(map, &spans, &bridge_spec(run.to - run.from, run.wet))
            {
                notes.push(format!(
                    "{} {:.0}–{:.0} m: no structure: {error}",
                    run.road, run.from, run.to
                ));
            }
        }
    }
    notes
}

/// A bridge `length` long: a viaduct if it is long and not over water.
fn bridge_spec(length: f64, over_water: bool) -> StructureSpec {
    StructureSpec::Bridge(BridgeSpec {
        form: if length >= 100.0 && !over_water {
            BridgeForm::Viaduct
        } else {
            BridgeForm::Bridge
        },
        ..BridgeSpec::default()
    })
}

/// The bridges of carriageways that share a deck, gathered: each deck is the runs
/// that run beside one another — of one corridor, on different roads — as
/// `(run, from, to)`, the longest first, since a deck is laid out along its first
/// road.
///
/// Every run of a deck is reached out to the **union** of the deck: to the
/// stations beside the far ends of the others, so both carriageways' halves of
/// the deck begin and end together, across from each other — as far as the
/// road stands clear of the land by a deck's depth, and never on to another
/// structure or another of its own road's bridges. A run with nothing beside it is
/// a deck of its own.
fn shared_decks(runs: &[Run]) -> Vec<Vec<(usize, f64, f64)>> {
    // Which deck each run is on: the runs beside one another, joined.
    let mut deck: Vec<usize> = (0..runs.len()).collect();
    fn root(deck: &mut [usize], mut index: usize) -> usize {
        while deck[index] != index {
            deck[index] = deck[deck[index]];
            index = deck[index];
        }
        index
    }
    for a in 0..runs.len() {
        for b in a + 1..runs.len() {
            if runs[a].corridor == runs[b].corridor && runs[a].beside(&runs[b]) {
                let (ra, rb) = (root(&mut deck, a), root(&mut deck, b));
                deck[ra] = rb;
            }
        }
    }
    let depth = BridgeSpec::default().deck_depth;
    let mut out: Vec<Vec<(usize, f64, f64)>> = Vec::new();
    let mut seen: Vec<usize> = Vec::new();
    for first in 0..runs.len() {
        let key = root(&mut deck, first);
        if seen.contains(&key) {
            continue;
        }
        seen.push(key);
        let members: Vec<usize> = (0..runs.len())
            .filter(|index| root(&mut deck, *index) == key)
            .collect();
        let mut spans: Vec<(usize, f64, f64)> = members
            .iter()
            .map(|&index| {
                let run = &runs[index];
                let (mut from, mut to) = (run.from, run.to);
                // The stations beside the others' ends, on this road.
                for &other in members.iter().filter(|other| **other != index) {
                    for end in [runs[other].from, runs[other].to] {
                        let (near, distance) = run.nearest(runs[other].point_at(end));
                        if distance <= BESIDE {
                            from = from.min(run.rows[near].0);
                            to = to.max(run.rows[near].0);
                        }
                    }
                }
                // Out only over rows that may be bridged: clear of the land, not
                // on another structure, not another run of the same road.
                let others: Vec<(f64, f64)> = runs
                    .iter()
                    .enumerate()
                    .filter(|(o, r)| *o != index && r.road == run.road)
                    .map(|(_, r)| (r.from, r.to))
                    .collect();
                let open = |row: &(f64, Point3, f64, Class)| {
                    row.3 != Class::Fixed
                        && row.2 > depth
                        && !others.iter().any(|(a, b)| row.0 >= *a && row.0 <= *b)
                };
                let start = run.rows.iter().position(|row| row.0 >= run.from);
                let end = run.rows.iter().rposition(|row| row.0 <= run.to);
                let (mut low, mut high) = (run.from, run.to);
                if let (Some(start), Some(end)) = (start, end) {
                    for row in run.rows[..start].iter().rev() {
                        if row.0 < from - 1e-6 || !open(row) {
                            break;
                        }
                        low = row.0;
                    }
                    for row in &run.rows[end + 1..] {
                        if row.0 > to + 1e-6 || !open(row) {
                            break;
                        }
                        high = row.0;
                    }
                }
                (index, low, high)
            })
            .collect();
        spans.sort_by(|a, b| (b.2 - b.1).total_cmp(&(a.2 - a.1)));
        out.push(spans);
    }
    out
}

/// The stretches of `rows` of class `kind`: each long enough, those close together
/// joined, and each reached out to where it is no more than `extend` off the land.
fn runs_of(rows: &[(f64, f64, Class)], kind: Class, extend: f64) -> Vec<(f64, f64)> {
    let mut runs: Vec<(usize, usize)> = Vec::new();
    let mut start: Option<usize> = None;
    for (index, row) in rows.iter().enumerate() {
        if row.2 == kind {
            start.get_or_insert(index);
        } else if let Some(from) = start.take() {
            runs.push((from, index - 1));
        }
    }
    if let Some(from) = start {
        runs.push((from, rows.len() - 1));
    }
    // Joined across a short stretch of ground, but never across a structure the
    // caller put there.
    let mut joined: Vec<(usize, usize)> = Vec::new();
    for run in runs {
        if let Some(last) = joined.last_mut() {
            let gap = rows[run.0].0 - rows[last.1].0;
            let clear = rows[last.1..=run.0].iter().all(|row| row.2 != Class::Fixed);
            if gap < GAP && clear {
                last.1 = run.1;
                continue;
            }
        }
        joined.push(run);
    }
    let off = |row: &(f64, f64, Class)| match kind {
        Class::Bridge => row.1 > extend,
        _ => row.1 < -extend,
    };
    // Reached out, two that meet are one: each reaches over the stretch of
    // ground between them, and on through the other.
    let mut reached: Vec<(usize, usize)> = Vec::new();
    for (mut from, mut to) in joined {
        while from > 0 && rows[from - 1].2 != Class::Fixed && off(&rows[from - 1]) {
            from -= 1;
        }
        while to + 1 < rows.len() && rows[to + 1].2 != Class::Fixed && off(&rows[to + 1]) {
            to += 1;
        }
        match reached.last_mut() {
            Some(last) if from <= last.1 => last.1 = last.1.max(to),
            _ => reached.push((from, to)),
        }
    }
    reached
        .into_iter()
        .map(|(from, to)| (rows[from].0, rows[to].0))
        .filter(|(from, to)| to - from >= SHORTEST)
        .collect()
}

/// Where a road crosses over another with nothing under it, puts an overpass under
/// it; then derives every grade separation. A crossing too close to carry is left
/// for validation to report, and noted.
pub(crate) fn separate(map: &mut Map) -> Vec<String> {
    let mut notes = Vec::new();
    for crossing in structure::crossings(map) {
        if crossing.carried_by(map).is_some() {
            continue;
        }
        let strict = crossing.strict(map);
        let ((upper, us, uz), (lower, ls, lz)) = crossing.ordered();
        let (upper, lower) = (upper.clone(), lower.clone());
        let gap = uz - lz;
        if gap < OVERPASS_DECK + 0.5 {
            if strict {
                notes.push(format!(
                    "{upper} at {us:.0} m and {lower} at {ls:.0} m cross {gap:.1} m apart: too \
                     close for a bridge; lift one of them"
                ));
            }
            continue;
        }
        if gap < CLEARANCE + OVERPASS_DECK {
            notes.push(format!(
                "{upper} at {us:.0} m clears {lower} by {:.1} m, under the {CLEARANCE} m a \
                 vehicle needs",
                gap - OVERPASS_DECK
            ));
        }
        let reach = abutment_reach(gap - OVERPASS_DECK);
        let mut span = structure::span_across(map, &upper, us, &lower, ls);
        span.from = (span.from - reach).max(0.0);
        let length = map
            .road(&upper)
            .and_then(|road| road.horizontal_length().ok())
            .unwrap_or(span.to);
        span.to = (span.to + reach).min(length);
        let spec = StructureSpec::Bridge(BridgeSpec::for_form(BridgeForm::Overpass));
        if let Err(error) = structure::place(map, &[span], &spec) {
            notes.push(format!("{upper} over {lower}: no overpass: {error}"));
        }
    }
    notes
}

/// How far past what it crosses a bridge reaches, for the land to come down from
/// its abutments to the road below at a fill's slope: `height` over it.
pub(crate) fn abutment_reach(height: f64) -> f64 {
    2.0 + height.max(0.0) * FILL
}

/// How far a road may stand off the natural land and still have a frontage,
/// metres.
const FRONTAGE: f64 = 1.5;

/// The stretches of `roads` that stand more than [`FRONTAGE`] off the natural land
/// — an embankment, a cutting — each as an outline reaching a lot's depth past the
/// road, for buildings to keep out of.
pub(crate) fn off_the_land(map: &Map, roads: &[RoadId], natural: &Natural) -> Vec<Vec<PlanPoint>> {
    let mut rings = Vec::new();
    for id in roads {
        let Some(road) = map.road(id) else { continue };
        let Ok(length) = road.horizontal_length() else {
            continue;
        };
        let count = (length / STEP).ceil().max(1.0) as usize;
        let mut run: Option<f64> = None;
        let close = |from: f64, to: f64, rings: &mut Vec<Vec<PlanPoint>>| {
            let span = RoadSpan::new(id.clone(), (from - 10.0).max(0.0), (to + 10.0).min(length));
            if span.length() > 1.0 {
                if let Ok(ring) = structure::outline(map, &[span], 25.0) {
                    rings.push(plan_of(&ring));
                }
            }
        };
        for index in 0..=count {
            let station = length * index as f64 / count as f64;
            let Ok(sample) = road
                .reference_line
                .sample_at(station, map.metadata.sampling)
            else {
                continue;
            };
            let p = sample.point;
            // A stretch on a structure is no cutting or embankment: a bored tunnel
            // has the land whole over it, and a deck keeps the town out on its own.
            let off = road.structure.at(station).is_none()
                && (p.z - natural.height(p.x, p.y)).abs() > FRONTAGE;
            match (off, run) {
                (true, None) => run = Some(station),
                (false, Some(from)) => {
                    close(from, station, &mut rings);
                    run = None;
                }
                _ => {}
            }
        }
        if let Some(from) = run {
            close(from, length, &mut rings);
        }
    }
    rings
}

/// The land's cut and fill along the fitted roads where they are on the ground:
/// from each edge a slope runs out at [`FILL`] down to the natural land, or at
/// [`CUT`] up to it. Each slope's far edge is a breakline; what lies between it
/// and the road is shaped by the two, and is a land cover — an embankment or a
/// cutting.
pub(crate) struct Earthworks {
    pub lines: Vec<Line>,
    pub holes: Vec<Vec<PlanPoint>>,
    /// `(kind, outline)`, at the land's height.
    pub covers: Vec<(String, Vec<Point3>)>,
    /// The road each of `covers` is the slope of.
    pub owners: Vec<RoadId>,
}

///
/// The edges of every road in `drawn` — an ordinary road, drawn with its vertices
/// as far apart as its caller liked — are read every [`STEP`] between their
/// vertices too; a corridor's roads have a vertex every step already.
pub(crate) fn earthworks(
    map: &Map,
    roads: &[RoadId],
    drawn: &[RoadId],
    natural: &Natural,
) -> Earthworks {
    let mut out = Earthworks {
        lines: Vec::new(),
        holes: Vec::new(),
        covers: Vec::new(),
        owners: Vec::new(),
    };
    // Every road's outline, to stop a slope where it runs into another road.
    let mut edges = Segments::new(20.0);
    for road in map.roads.iter() {
        for (left, right) in at_grade_edges(map, road) {
            edges.insert_polyline(&plan_of(&left));
            edges.insert_polyline(&plan_of(&right));
        }
    }
    for id in roads {
        let Some(road) = map.road(id) else { continue };
        if road.is_connector() {
            continue;
        }
        let dense = drawn.contains(id);
        for (run, (left, right)) in at_grade_edges(map, road).into_iter().enumerate() {
            for (side, points, sign) in [("left", left, 1.0), ("right", right, -1.0)] {
                let points = if dense { every_step(&points) } else { points };
                slopes(
                    &format!("{}/{run}/{side}", id.local_name()),
                    &points,
                    sign,
                    natural,
                    &edges,
                    &mut out,
                );
            }
        }
        out.owners.resize(out.covers.len(), id.clone());
    }
    out
}

/// `points` with more between any two further apart than a [`STEP`], evenly, so
/// none are.
fn every_step(points: &[Point3]) -> Vec<Point3> {
    let mut out = Vec::with_capacity(points.len());
    for pair in points.windows(2) {
        let (a, b) = (pair[0], pair[1]);
        let count = (a.horizontal_distance_to(b) / STEP).ceil().max(1.0) as usize;
        out.extend((0..count).map(|k| a.lerp(b, k as f64 / count as f64)));
    }
    out.extend(points.last().copied());
    out
}

/// The slope out from one edge: `sign` +1 for a left edge, whose outside is to
/// the left of the way the points run.
fn slopes(
    key: &str,
    points: &[Point3],
    sign: f64,
    natural: &Natural,
    edges: &Segments,
    out: &mut Earthworks,
) {
    if points.len() < 2 {
        return;
    }
    // Each edge point's far edge, or none where the land already meets the road.
    let mut feet: Vec<Option<(Point3, bool)>> = Vec::with_capacity(points.len());
    for index in 0..points.len() {
        let a = points[index.saturating_sub(1)];
        let b = points[(index + 1).min(points.len() - 1)];
        let (dx, dy) = (b.x - a.x, b.y - a.y);
        let len = dx.hypot(dy).max(1e-9);
        let (nx, ny) = (-dy / len * sign, dx / len * sign);
        let p = points[index];
        let difference = p.z - natural.height(p.x, p.y);
        if difference.abs() < 0.3 {
            feet.push(None);
            continue;
        }
        let fill = difference > 0.0;
        let mut found = None;
        let mut x = 0.5;
        while x <= FURTHEST {
            let (qx, qy) = (p.x + nx * x, p.y + ny * x);
            // Into another road: the slope stops, and the land is left to it.
            if x > 1.0 && edges.within([qx, qy], 0.5).is_some() {
                break;
            }
            let land = natural.height(qx, qy);
            let slope = if fill { p.z - x / FILL } else { p.z + x / CUT };
            if (fill && slope <= land) || (!fill && slope >= land) {
                found = Some((Point3::new(qx, qy, land), fill));
                break;
            }
            x += 0.5;
        }
        feet.push(found.filter(|(foot, _)| foot.horizontal_distance_to(p) > 0.75));
    }
    // Runs of the same kind of slope, each its own line.
    let mut start = 0;
    let mut count = 0;
    while start < points.len() {
        let Some((_, fill)) = feet[start] else {
            start += 1;
            continue;
        };
        let mut end = start;
        while end + 1 < points.len() && feet[end + 1].is_some_and(|(_, f)| f == fill) {
            end += 1;
        }
        if end > start {
            let edge: Vec<Point3> = points[start..=end].to_vec();
            let foot: Vec<Point3> = feet[start..=end]
                .iter()
                .map(|f| f.expect("in a run").0)
                .collect();
            let kind = if fill { "fill_toe" } else { "cut_crest" };
            out.lines.push(Line {
                key: format!("{key}/{kind}/{count}"),
                kind,
                points: foot.clone(),
                closed: false,
            });
            let ring: Vec<Point3> = edge.iter().copied().chain(foot.into_iter().rev()).collect();
            out.holes.push(plan_of(&ring));
            out.covers
                .push((if fill { "embankment" } else { "cutting" }.to_owned(), ring));
            count += 1;
        }
        start = end + 1;
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_bored_tunnel_is_no_cutting_to_keep_the_town_off() {
        use roadgen_core::prelude::*;
        use roadgen_core::structure::{TunnelForm, TunnelSpec};
        // 30 m under level land the whole way, in a bored tunnel from 100 to 300 m.
        let mut builder = MapBuilder::default();
        let road = builder
            .add_road(
                RoadSpec::line(
                    Point3::new(0.0, 0.0, -30.0),
                    Point3::new(400.0, 0.0, -30.0),
                    vec![
                        LaneSpec::new(PositiveWidth::new(3.5).unwrap(), Direction::Forward),
                        LaneSpec::new(PositiveWidth::new(3.5).unwrap(), Direction::Backward),
                    ],
                )
                .unwrap(),
            )
            .unwrap();
        builder
            .add_tunnel(
                vec![RoadSpan::new(road.clone(), 100.0, 300.0)],
                TunnelSpec {
                    form: TunnelForm::Bored,
                    ..TunnelSpec::default()
                },
            )
            .unwrap();
        let map = builder.finish().unwrap();
        let natural = Natural {
            field: None,
            rises: &[],
        };
        let rings = off_the_land(map.as_map(), &[road], &natural);
        let inside = |p: PlanPoint| {
            rings
                .iter()
                .any(|ring| roadgen_core::geometry::plan::ring_contains(ring, p))
        };
        assert!(
            inside([50.0, 0.0]) && inside([350.0, 0.0]),
            "the approaches are cut"
        );
        assert!(!inside([200.0, 0.0]), "but not the tunnel");
    }

    #[test]
    fn a_stretch_high_above_the_land_is_a_bridge_reaching_to_its_abutments() {
        // 0–100 m on the ground, 100–200 m 12 m up, then back down.
        let rows: Vec<(f64, f64, Class)> = (0..=60)
            .map(|i| {
                let s = i as f64 * 5.0;
                let d = if (100.0..=200.0).contains(&s) {
                    12.0
                } else if (90.0..100.0).contains(&s) || (200.0..210.0).contains(&s) {
                    6.0
                } else {
                    0.0
                };
                let class = if d > BRIDGE {
                    Class::Bridge
                } else {
                    Class::Ground
                };
                (s, d, class)
            })
            .collect();
        let runs = runs_of(&rows, Class::Bridge, ABUTMENT);
        assert_eq!(runs, vec![(90.0, 205.0)]);
    }

    #[test]
    fn two_bridges_close_together_are_one() {
        let rows: Vec<(f64, f64, Class)> = (0..=60)
            .map(|i| {
                let s = i as f64 * 5.0;
                let high = (50.0..100.0).contains(&s) || (130.0..180.0).contains(&s);
                (
                    s,
                    if high { 12.0 } else { 0.0 },
                    if high { Class::Bridge } else { Class::Ground },
                )
            })
            .collect();
        assert_eq!(runs_of(&rows, Class::Bridge, ABUTMENT), vec![(50.0, 175.0)]);
    }

    #[test]
    fn two_bridges_reaching_out_over_the_ground_between_them_are_one() {
        // Too far apart to be joined, but the ground between stands high enough
        // for each to reach out over it to the other: one bridge, not the same
        // one twice.
        let rows: Vec<(f64, f64, Class)> = (0..=60)
            .map(|i| {
                let s = i as f64 * 5.0;
                let high = (50.0..100.0).contains(&s) || (200.0..250.0).contains(&s);
                (
                    s,
                    if high { 12.0 } else { 6.0 },
                    if high { Class::Bridge } else { Class::Ground },
                )
            })
            .collect();
        assert_eq!(runs_of(&rows, Class::Bridge, ABUTMENT), vec![(0.0, 300.0)]);
    }

    /// A road 300 m long along `y`, east, `height` over the level land.
    fn level_road(
        builder: &mut roadgen_core::prelude::MapBuilder,
        name: &str,
        y: f64,
        height: f64,
    ) {
        use roadgen_core::prelude::*;
        builder
            .add_road(
                RoadSpec::line(
                    Point3::new(0.0, y, height),
                    Point3::new(300.0, y, height),
                    vec![
                        LaneSpec::new(PositiveWidth::new(3.5).unwrap(), Direction::Forward),
                        LaneSpec::new(PositiveWidth::new(3.5).unwrap(), Direction::Backward),
                    ],
                )
                .unwrap()
                .with_name(name),
            )
            .unwrap();
    }

    #[test]
    fn a_road_beside_an_embankment_stands_over_the_embankment_not_the_natural_land() {
        use roadgen_core::prelude::*;
        // 9 m over the level land, a road goes on a bridge. Beside another on a
        // 6 m embankment, 3 m clear of it, it stands over that embankment's
        // slope, not high enough to: on an embankment too, not a deck the slope
        // reaches up under.
        let natural = Natural {
            field: None,
            rises: &[],
        };
        let bridges = |roads: &[(&str, f64, f64)]| {
            let mut builder = MapBuilder::default();
            for (name, y, height) in roads {
                level_road(&mut builder, name, *y, *height);
            }
            let mut map = builder.finish().unwrap().into_map();
            let chosen: Vec<(RoadId, Option<String>)> = roads
                .iter()
                .map(|(name, _, _)| (RoadId::new(*name), None))
                .collect();
            let notes = choose_structures(&mut map, &chosen, &[], &natural, &[]);
            assert!(notes.is_empty(), "{notes:#?}");
            map.structures.len()
        };
        assert_eq!(bridges(&[("high", 0.0, 9.0)]), 1);
        assert_eq!(bridges(&[("high", 0.0, 9.0), ("embanked", 10.0, 6.0)]), 0);
        // Two both high enough, side by side, are both on bridges: neither has a
        // slope under the other.
        assert_eq!(bridges(&[("high", 0.0, 9.0), ("other", 10.0, 9.0)]), 2);
    }

    /// A carriageway 300 m long along `y`, drawn east (`east`) or west, 12 m off
    /// the land, bridged from `from` to `to`; and `fixed`, a stretch of it already
    /// on another structure.
    fn run(name: &str, y: f64, east: bool, from: f64, to: f64, fixed: (f64, f64)) -> Run {
        Run {
            road: RoadId::new(name),
            corridor: "E1".into(),
            from,
            to,
            rows: (0..=60)
                .map(|i| {
                    let s = i as f64 * 5.0;
                    let x = if east { s } else { 300.0 - s };
                    let class = if (fixed.0..=fixed.1).contains(&s) {
                        Class::Fixed
                    } else {
                        Class::Bridge
                    };
                    (s, Point3::new(x, y, 12.0), 12.0, class)
                })
                .collect(),
            wet: false,
        }
    }

    #[test]
    fn two_carriageways_bridged_beside_each_other_share_a_deck_reaching_over_both() {
        // The east carriageway bridged from x 100 to 200, the west from 110 to 220.
        let runs = [
            run("east", -3.0, true, 100.0, 200.0, (-1.0, -1.0)),
            run("west", 3.0, false, 80.0, 190.0, (-1.0, -1.0)),
        ];
        let decks = shared_decks(&runs);
        assert_eq!(decks.len(), 1);
        let mut deck = decks[0].clone();
        deck.sort_by_key(|(index, _, _)| *index);
        // Each reaches out to x 100–220: the union.
        assert_eq!(deck, vec![(0, 100.0, 220.0), (1, 80.0, 200.0)]);
    }

    #[test]
    fn a_shared_deck_stops_short_of_a_structure_already_there() {
        // The west carriageway is on another structure from x 90 to 105.
        let runs = [
            run("east", -3.0, true, 100.0, 200.0, (-1.0, -1.0)),
            run("west", 3.0, false, 80.0, 190.0, (195.0, 210.0)),
        ];
        let mut deck = shared_decks(&runs).remove(0);
        deck.sort_by_key(|(index, _, _)| *index);
        assert_eq!(deck, vec![(0, 100.0, 220.0), (1, 80.0, 190.0)]);
    }

    /// A piece of a carriageway along `y` from x `x0` to `x0 + 300`, drawn east,
    /// 12 m off the land, bridged from `from` to `to` along it.
    fn piece(name: &str, y: f64, x0: f64, from: f64, to: f64) -> Run {
        let mut run = run(name, y, true, from, to, (-1.0, -1.0));
        for row in &mut run.rows {
            row.1.x += x0;
        }
        run
    }

    #[test]
    fn a_bridge_over_the_join_of_two_pieces_of_one_carriageway_is_not_one_deck() {
        // Split at a slip-road nose: one piece ends at x 300, the next begins 20 m
        // on; the land bridges the last 100 m of the one and the first of the next.
        let runs = [
            piece("left_0", -3.0, 0.0, 200.0, 300.0),
            piece("left_1", -3.0, 320.0, 0.0, 100.0),
        ];
        assert!(!runs[0].beside(&runs[1]) && !runs[1].beside(&runs[0]));
        assert_eq!(
            shared_decks(&runs),
            vec![vec![(0, 200.0, 300.0)], vec![(1, 0.0, 100.0)]]
        );
    }

    #[test]
    fn a_road_passing_across_a_bridge_nearby_does_not_share_its_deck() {
        // Square across the first, 10 m to its side at the nearest.
        let mut across = run("across", 0.0, true, 50.0, 250.0, (-1.0, -1.0));
        for row in &mut across.rows {
            row.1 = Point3::new(150.0, row.0 - 160.0, 12.0);
        }
        let runs = [run("east", -3.0, true, 100.0, 200.0, (-1.0, -1.0)), across];
        assert!(!runs[0].beside(&runs[1]) && !runs[1].beside(&runs[0]));
        assert_eq!(shared_decks(&runs).len(), 2);
    }

    #[test]
    fn two_pieces_of_one_carriageway_share_the_deck_of_the_other_beside_both() {
        // The other carriageway, drawn west along x 600 to 0, bridged from x 200
        // to 420: beside both pieces.
        let mut other = run("right_0", 3.0, false, 180.0, 400.0, (-1.0, -1.0));
        other.rows = (0..=120)
            .map(|i| {
                let s = i as f64 * 5.0;
                (s, Point3::new(600.0 - s, 3.0, 12.0), 12.0, Class::Bridge)
            })
            .collect();
        let runs = [
            piece("left_0", -3.0, 0.0, 200.0, 300.0),
            piece("left_1", -3.0, 320.0, 0.0, 100.0),
            other,
        ];
        let decks = shared_decks(&runs);
        assert_eq!(decks.len(), 1, "{decks:?}");
        assert_eq!(decks[0].len(), 3);
    }

    #[test]
    fn carriageways_bridged_at_different_places_are_on_decks_of_their_own() {
        let runs = [
            run("east", -3.0, true, 20.0, 80.0, (-1.0, -1.0)),
            run("west", 3.0, false, 20.0, 80.0, (-1.0, -1.0)),
        ];
        // x 20–80 and x 220–280: never beside each other.
        let decks = shared_decks(&runs);
        assert_eq!(decks, vec![vec![(0, 20.0, 80.0)], vec![(1, 20.0, 80.0)]]);
    }
}
